import{_ as e,a0 as i,w as s,s as a,ao as l,I as r,x as o,a1 as u,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"小技巧：如何修復Lubuntu中的Docky混合錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"小技巧：如何修復Lubuntu中的Docky混合錯誤 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"小技巧：如何修復Lubuntu中的Docky混合錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"小技巧：如何修復Lubuntu中的Docky混合錯誤 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141112 [Quick Tip] How To Fix Docky Compositing Error In Lubuntu","title":"小技巧：如何修復Lubuntu中的Docky混合錯誤","tag":"201411","desc":""},"relativePath":"201411/20141112 [Quick Tip] How To Fix Docky Compositing Error In Lubuntu.md","filePath":"[post].md"}'),d={name:"201411/20141112 [Quick Tip] How To Fix Docky Compositing Error In Lubuntu.md"};function m(g,t,k,c,T,D){const n=i("Link");return s(),a("div",null,[t[13]||(t[13]=l(`<h1 id="小技巧-如何修復lubuntu中的docky混合錯誤" tabindex="-1">小技巧：如何修復Lubuntu中的Docky混合錯誤 <a class="header-anchor" href="#小技巧-如何修復lubuntu中的docky混合錯誤" aria-label="Permalink to “小技巧：如何修復Lubuntu中的Docky混合錯誤”">​</a></h1><p>總所周知，<strong>Docky</strong>是Unix/Linux類系統中的輕量級應用啓動器。我是 Lubuntu 和 Docky 的忠實粉絲，因為它們不需要佔用我的所有系統資源，這樣就可以同時運行更多應用。我在筆記本上使用Docky應用啓動器，系統為Lubuntu 14.04.</p><p>但是，如果你使用LXDE發行版，你也許肯定遇到過使用Docky時報混合的錯誤。看下面的截圖。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Docky.png" alt=""></p><p>如果不開啓混合功能，就不能使用Docky一些特別功能，如3D背景、自動隱藏。如果你想開啓這些Docky的功能，那麼你需要在你的LXDE系統中開啓混合功能。</p><p>就像這樣，首先安裝 <strong>xcompmgr</strong>包：</p><pre><code>sudo apt-get install xcompmgr
</code></pre><p>然後，選擇<strong>菜單（Menu） -&gt; 偏好（Preferences） -&gt; LXSession默認程序（Default applications for LXSession）</strong>。選擇自動開始（Autostart）選項卡。 在<strong>（+增加）+Add</strong>框中輸入“<strong>@xcompmgr -n</strong>”不帶引號。最後點擊增加按鈕。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/LXSession-configuration_002.png" alt=""></p><p>這樣就搞定了。關掉LXSession配置窗口，註銷或重啓系統。之後，你就可以看見混合功能已經打開。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/unknown_006.png" alt=""></p><p>這時，你就可以使用3D背景和隱藏功能，如自動隱藏（Auto-hide），Intellihide和窗口閃爍（Window dodge）等。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Docky-Settings_003.png" alt=""></p><p>搞定！乾杯！</p><hr>`,15)),r("p",null,[t[1]||(t[1]=o("via: ",-1)),u(n,{href:"http://www.unixmen.com/quick-tip-fix-docky-compositing-error-lubuntu/"},{default:p(()=>[...t[0]||(t[0]=[o("http://www.unixmen.com/quick-tip-fix-docky-compositing-error-lubuntu/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=o("作者：",-1)),u(n,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...t[2]||(t[2]=[o("SK",-1)])]),_:1}),t[6]||(t[6]=o(" 譯者：",-1)),u(n,{href:"http://www.vicyu.net"},{default:p(()=>[...t[3]||(t[3]=[o("Vic020/VicYu",-1)])]),_:1}),t[7]||(t[7]=o(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=o("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[o("Linux中國",-1)])]),_:1}),t[12]||(t[12]=o(" 榮譽推出",-1))])])}const w=e(d,[["render",m]]);export{x as __pageData,w as default};
